import java.util.*;

public class Main {
    int[] twoSum(int[] nums, int target) {
        int n = nums.length;
        for (int i = 0; i < n; i++) {                             // try every index as the first number
            for (int j = i + 1; j < n; j++) {                       // try every later index as the second number
                if (nums[i] + nums[j] == target) {
                    return new int[]{i, j};                             // found the matching pair
                }
            }
        }
        return new int[]{};
    }

    public static void main(String[] args) {
        int[] nums = {2, 7, 11, 15};
        int target = 9;
        Main solution = new Main();
        System.out.println(Arrays.toString(solution.twoSum(nums, target)));
    }
}

