import java.util.*;

public class Main {
    int[] twoSum(int[] nums, int target) {
        Map<Integer, Integer> seen = new HashMap<>();             // maps a value already visited to its index
        for (int i = 0; i < nums.length; i++) {
            int complement = target - nums[i];
            if (seen.containsKey(complement)) {
                return new int[]{seen.get(complement), i};              // complement was already seen, pair found
            }
            seen.put(nums[i], i);                                    // record this value for future lookups
        }
        return new int[]{};
    }

    public static void main(String[] args) {
        int[] nums = {2, 7, 11, 15};
        int target = 9;
        Main solution = new Main();
        System.out.println(Arrays.toString(solution.twoSum(nums, target)));
    }
}

